#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int u, v;
    long long w;
} Edge;

int compare_edges(const void *a, const void *b) {
    long long w1 = ((const Edge *)a)->w;
    long long w2 = ((const Edge *)b)->w;
    if (w1 < w2) return -1;
    if (w1 > w2) return 1;
    return 0;
}

int find_set(int i, int *parent) {
    int root = i;
    while (root != parent[root]) {
        root = parent[root];
    }
    int curr = i;
    while (curr != root) {
        int nxt = parent[curr];
        parent[curr] = root;
        curr = nxt;
    }
    return root;
}

int main() {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int total_cells = N * M;
    long long *P = (long long *)malloc(total_cells * sizeof(long long));
    for (int i = 0; i < total_cells; i++) {
        scanf("%lld", &P[i]);
    }

    if (total_cells == 1) {
        printf("%lld\n", P[0]);
        free(P);
        return 0;
    }

    int max_edges = 2 * total_cells;
    Edge *edges = (Edge *)malloc(max_edges * sizeof(Edge));
    int edge_count = 0;

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            int u = i * M + j;
            // Vizinho à direita
            if (j + 1 < M) {
                int v = i * M + (j + 1);
                long long w = P[u] > P[v] ? P[u] : P[v];
                edges[edge_count++] = (Edge){u, v, w};
            }
            // Vizinho abaixo
            if (i + 1 < N) {
                int v = (i + 1) * M + j;
                long long w = P[u] > P[v] ? P[u] : P[v];
                edges[edge_count++] = (Edge){u, v, w};
            }
        }
    }

    qsort(edges, edge_count, sizeof(Edge), compare_edges);

    int max_nodes = 2 * total_cells;
    long long *sum = (long long *)malloc(max_nodes * sizeof(long long));
    long long *ans = (long long *)malloc(max_nodes * sizeof(long long));
    long long *weight = (long long *)malloc(max_nodes * sizeof(long long));
    int *left_child = (int *)malloc(max_nodes * sizeof(int));
    int *right_child = (int *)malloc(max_nodes * sizeof(int));
    int *dsu_parent = (int *)malloc(max_nodes * sizeof(int));

    for (int i = 0; i < total_cells; i++) {
        sum[i] = P[i];
        left_child[i] = -1;
        right_child[i] = -1;
        dsu_parent[i] = i;
        weight[i] = 0;
    }

    int node_cnt = total_cells;
    for (int i = 0; i < edge_count; i++) {
        int ru = find_set(edges[i].u, dsu_parent);
        int rv = find_set(edges[i].v, dsu_parent);

        if (ru != rv) {
            int new_node = node_cnt++;
            left_child[new_node] = ru;
            right_child[new_node] = rv;
            weight[new_node] = edges[i].w;
            sum[new_node] = sum[ru] + sum[rv];

            dsu_parent[ru] = new_node;
            dsu_parent[rv] = new_node;
            dsu_parent[new_node] = new_node;
        }
    }

    int root = node_cnt - 1;
    ans[root] = sum[root];

    // BFS para propagar a resposta da raiz para as folhas
    int *queue = (int *)malloc(max_nodes * sizeof(int));
    int head = 0, tail = 0;
    queue[tail++] = root;

    while (head < tail) {
        int u = queue[head++];
        int l = left_child[u];
        int r = right_child[u];

        if (l != -1) {
            if (sum[l] >= weight[u]) {
                ans[l] = ans[u];
            } else {
                ans[l] = sum[l];
            }
            queue[tail++] = l;
        }

        if (r != -1) {
            if (sum[r] >= weight[u]) {
                ans[r] = ans[u];
            } else {
                ans[r] = sum[r];
            }
            queue[tail++] = r;
        }
    }

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            int id = i * M + j;
            printf("%lld%c", ans[id], (j == M - 1) ? '\n' : ' ');
        }
    }

    // Liberação de memória
    free(P);
    free(edges);
    free(sum);
    free(ans);
    free(weight);
    free(left_child);
    free(right_child);
    free(dsu_parent);
    free(queue);

    return 0;
}
